        if 'task-695a882c' in content_str:
            print(f"\n--- Task mentioned at message {i}: ---")
            print(content_content[:500] if (content_content := get_text_repr(msg)) else "")

def get_text_repr(msg):
    text_parts = []
    for k, v in msg.items():
        t = type(v).__name__
        if isinstance(v, list):
            try:
                if len(v) < 10:
                    text_parts.append(f"{k}: [{v}]")
                elif all(isinstance(x, int) for row in v for x in row):
                    text_parts.append(f"{k}: matrix ({len(v)} rows)")
            except:
                pass
        elif isinstance(v, str):
            text_parts.append(f"{k}: str={len(v)} chars")
        else:
            text_parts.append(f"{k}: {t}")
    return " ".join(text_parts[:20])

